// =========================================================================
// STAGE: Normalize Trends (Source Abstraction)
// Converts raw RSS/XML into common TrendzNow structure:
// {
//   keyword, country_code, category, search_volume, trend_velocity,
//   ranking, source, related_queries, normalized_keyword
// }
// =========================================================================

const rawXml = $input.first().json.data || $input.first().json.body || $input.first().json;
const xmlText = typeof rawXml === 'string' ? rawXml : JSON.stringify(rawXml);

const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
let match;
let rank = 1;

while ((match = itemRegex.exec(xmlText)) !== null) {
  const itemContent = match[1];

  // Extract Title (Keyword)
  const titleMatch = /<title>([\s\S]*?)<\/title>/i.exec(itemContent);
  const rawKeyword = titleMatch ? titleMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').trim() : '';

  // Extract Approx Traffic (Search Volume)
  const trafficMatch = /<ht:approx_traffic>([\s\S]*?)<\/ht:approx_traffic>/i.exec(itemContent);
  let searchVolume = null;
  if (trafficMatch) {
    const rawTraffic = trafficMatch[1].replace(/\D/g, '');
    if (rawTraffic) {
      searchVolume = parseInt(rawTraffic, 10);
      if (trafficMatch[1].toLowerCase().includes('k')) {
        searchVolume = searchVolume * 1000;
      } else if (trafficMatch[1].toLowerCase().includes('m')) {
        searchVolume = searchVolume * 1000000;
      }
    }
  }

  // Extract Related Queries / News Item Titles
  const relatedQueries = [];
  const newsTitleRegex = /<ht:news_item_title>([\s\S]*?)<\/ht:news_item_title>/gi;
  let newsMatch;
  while ((newsMatch = newsTitleRegex.exec(itemContent)) !== null) {
    const newsTitle = newsMatch[1]
      .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1')
      .replace(/&apos;/g, "'")
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, '&')
      .trim();
    if (newsTitle && !relatedQueries.includes(newsTitle)) {
      relatedQueries.push(newsTitle);
    }
  }

  if (rawKeyword) {
    // Normalization rules
    const normalizedKeyword = rawKeyword
      .normalize('NFKC')
      .toLowerCase()
      .trim()
      .replace(/\s+/g, ' ');

    items.push({
      json: {
        keyword: rawKeyword,
        normalized_keyword: normalizedKeyword,
        country_code: 'US',
        category: 'General',
        search_volume: searchVolume,
        trend_velocity: null,
        ranking: rank,
        source: 'google_trends_rss',
        related_queries: relatedQueries
      }
    });
    rank++;
  }
}

return items;

// =========================================================================
// STAGE: Validate Records & Deduplicate in Batch
// Ensures records are well-formed and removes intra-batch duplicates.
// =========================================================================

const seen = new Set();
const validated = [];

for (const item of $input.all()) {
  const data = item.json;
  if (!data.keyword || !data.normalized_keyword) continue;
  if (typeof data.keyword !== 'string' || data.keyword.trim().length === 0) continue;

  const key = `${data.normalized_keyword}::${data.country_code}`;
  if (seen.has(key)) continue;
  seen.add(key);

  validated.push(item);
}

return validated;

// =========================================================================
// STAGE: Calculate Initial Metrics
// Deterministic scoring (No LLM/AI):
// - Opportunity Score (0–100)
// - Risk Score (0–100)
// - Status = "detected"
// =========================================================================

const HIGH_RISK_KEYWORDS = [
  'death', 'dead', 'dies', 'died', 'killing', 'killed', 'murder', 'murdered',
  'shooting', 'shot', 'crash', 'fatal', 'suicide', 'attack', 'bomb', 'terror',
  'war', 'conflict', 'arrest', 'arrested', 'indicted', 'fraud', 'scandal',
  'emergency', 'disaster', 'outbreak', 'virus', 'overdose'
];

return $input.all().map(item => {
  const data = item.json;
  const kw = data.normalized_keyword;

  // 1. Opportunity Score (0–100)
  // Formula: 70% volume weight + 30% ranking bonus
  let volumeScore = 20;
  if (data.search_volume) {
    if (data.search_volume >= 500000) volumeScore = 100;
    else if (data.search_volume >= 200000) volumeScore = 85;
    else if (data.search_volume >= 100000) volumeScore = 70;
    else if (data.search_volume >= 50000) volumeScore = 55;
    else if (data.search_volume >= 20000) volumeScore = 40;
    else volumeScore = 25;
  }

  let rankScore = 10;
  if (data.ranking) {
    if (data.ranking <= 3) rankScore = 100;
    else if (data.ranking <= 5) rankScore = 80;
    else if (data.ranking <= 10) rankScore = 60;
    else if (data.ranking <= 15) rankScore = 40;
    else rankScore = 20;
  }

  const opportunityScore = Math.min(100, Math.round(volumeScore * 0.7 + rankScore * 0.3));

  // 2. Risk Score (0–100)
  // Deterministic keyword/category review flag for sensitive/unconfirmed topics
  let riskScore = 10; // Default low risk baseline
  const containsHighRisk = HIGH_RISK_KEYWORDS.some(term => kw.includes(term));
  if (containsHighRisk) {
    riskScore = 75; // Flag for priority editorial review
  }

  const now = new Date().toISOString();

  return {
    json: {
      ...data,
      opportunity_score: opportunityScore,
      risk_score: riskScore,
      status: 'detected',
      first_detected_at: now,
      last_detected_at: now,
      created_at: now,
      updated_at: now
    }
  };
});
